class Solution { private int lca(int a,int b,int[][] up,int[] depth){if(depth[a]<depth[b]){int swap=a;a=b;b=swap;}int difference=depth[a]-depth[b];for(int bit=0;bit<up.length;bit++)if(((difference>>bit)&1)==1)a=up[bit][a];if(a==b)return a;for(int bit=up.length-1;bit>=0;bit--)if(up[bit][a]!=up[bit][b]){a=up[bit][a];b=up[bit][b];}return up[0][a];}public int[] minOperationsQueries(int n,int[][] edges,int[][] queries){List<List<int[]>> graph=new ArrayList<>();for(int i=0;i<n;i++)graph.add(new ArrayList<>());for(int[] edge:edges){graph.get(edge[0]).add(new int[]{edge[1],edge[2]-1});graph.get(edge[1]).add(new int[]{edge[0],edge[2]-1});}int levels=1;while((1<<levels)<=n)levels++;int[][] up=new int[levels][n],prefix=new int[n][26];int[] depth=new int[n];Arrays.fill(up[0],-1);up[0][0]=0;Deque<Integer> queue=new ArrayDeque<>();queue.add(0);while(!queue.isEmpty()){int node=queue.removeFirst();for(int[] edge:graph.get(node)){int next=edge[0];if(next==up[0][node])continue;up[0][next]=node;depth[next]=depth[node]+1;prefix[next]=prefix[node].clone();prefix[next][edge[1]]++;queue.addLast(next);}}for(int bit=1;bit<levels;bit++)for(int node=0;node<n;node++)up[bit][node]=up[bit-1][up[bit-1][node]];int[] answer=new int[queries.length];for(int i=0;i<queries.length;i++){int u=queries[i][0],v=queries[i][1],ancestor=lca(u,v,up,depth);int length=depth[u]+depth[v]-2*depth[ancestor],maximum=0;for(int weight=0;weight<26;weight++)maximum=Math.max(maximum,prefix[u][weight]+prefix[v][weight]-2*prefix[ancestor][weight]);answer[i]=length-maximum;}return answer;} }
